import {mountSentinel} from './sentinel-ui.js';
const root=document.querySelector('#workspace-content');

const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

const usd=v=>v==null?'Not entered':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(Number(v));

const pct=v=>Number.isFinite(Number(v))?(Number(v)*100).toFixed(1)+'%':'Unknown';

const help=(id,label)=>`<button type="button" class="metric-help" data-metric-help="${id}" aria-label="What does ${label} mean?">?</button>`;

const icon=(name)=>{const paths={overview:'M3 3h7v9H3z M14 3h7v5h-7z M14 12h7v9h-7z M3 16h7v5H3z',risk:'M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z',improve:'M9 18h6 M10 22h4 M12 2a7 7 0 0 0-4 12.7V17h8v-2.3A7 7 0 0 0 12 2z',holdings:'M3 3v18h18 M7 15l4-4 3 3 6-6',calendar:'M3 5h18v16H3z M3 10h18 M8 2v6 M16 2v6',news:'M4 3h16v18H4z M8 7h8 M8 11h8 M8 15h8',settings:'M4 3v18 M12 3v18 M20 3v18 M1 8h6 M9 16h6 M17 10h6'};return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.overview}"/></svg>`;};

let current,displayed,demo,previewBudget=false,previewPortfolio=false,refreshing=false,watchTimer,workspace='budget',view='overview',marketData;

async function api(path,method='GET',body){let sid;try{sid=localStorage.getItem('sid');}catch{}if(!sid)throw Error('Enable browser session storage to save your workspace.');const r=await fetch(path,{method,headers:{'Content-Type':'application/json','X-Session-Id':sid},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Error(d.error||'The workspace could not update.');return d;}

const status=text=>{document.querySelector('#workspace-status').textContent=text;};

async function run(fn){try{await fn();}catch(e){status(e.message);}}

function field(id,label,key){return `<label class="f" for="budget-${id}"><span>${label} ${help(key,label)}</span><input id="budget-${id}" name="${id}" inputmode="decimal" required placeholder="0.00" pattern="[0-9]+(\\.[0-9]{1,2})?"></label>`;}

const card=(title,body,extra='')=>`<article class="ws-card ${extra}"><header class="ws-card-h"><h3>${title}</h3></header>${body}</article>`;

root.innerHTML=`<div class="ws-shell"><aside class="ws-sidebar"><div class="ws-brand"><img src="/img/mentor-logo-suede.webp" alt="" width="32" height="32"><span>Mentor Labs<small>Your financial workspace</small></span></div><div class="workspace-tabs" role="group" aria-label="Workspace"><button type="button" data-workspace-tab="budget" aria-pressed="true">Budget</button><button type="button" data-workspace-tab="portfolio" aria-pressed="false">Portfolio</button></div><nav class="ws-nav" aria-label="Dashboard sections">${[['overview','Overview'],['risk','Review'],['improve','Explore tradeoffs'],['holdings','Plan & inputs'],['calendar','Calendar'],['news','News'],['settings','Guidelines']].map(([id,label])=>`<button type="button" data-ws-view="${id}" aria-pressed="${id==='overview'}">${icon(id)}<span>${label}</span>${id==='risk'?'<span id="ws-alert-count" class="ws-badge" hidden></span>':''}</button>`).join('')}</nav><div class="ws-sources"><p class="ws-eyebrow">Data sources</p><p id="ws-source-description">Your saved inputs<br>Manual entries & imports</p><p class="fine" id="ws-source-date">No linked account</p><details class="workspace-connections"><summary>Connection previews</summary><p class="fine">Bank and brokerage connections are planned. Manual entry and CSV import work now.</p><a href="https://plaid.com/docs/financial-insights/" target="_blank" rel="noopener noreferrer">Bank activity ↗</a><a href="https://docs.snaptrade.com/docs/account-data" target="_blank" rel="noopener noreferrer">Brokerage holdings ↗</a></details></div></aside><div class="ws-content"><header class="ws-topbar"><div><p class="ws-eyebrow" id="ws-workspace-label">Budget workspace</p><h2 id="ws-view-title">Overview</h2><p class="ws-sub" id="ws-view-sub">Your saved monthly plan</p></div><div class="ws-top-actions"><button class="btn" type="button" id="ws-export">Export review</button><button class="btn primary" type="button" id="ws-primary-action">Update budget</button></div></header><div id="workspace-preview" class="ws-preview" hidden></div><p id="workspace-status" role="status"></p><div class="ws-main"><section id="workspace-budget"><div data-ws-panel="overview"><div id="budget-overview" class="workspace-stats"></div><div class="ws-grid ws-two-one">${card('Monthly cash flow','<div id="budget-cashflow" class="ws-bars"></div><p class="fine">Based on your lowest saved take-home month and entered monthly costs.</p>')}${card('Cash cushion','<div id="budget-cushion"></div>')}</div><div class="ws-grid ws-three">${card('Where your money goes','<div id="budget-allocation"></div>')}${card('Your next step','<div id="budget-next"></div><button type="button" class="ws-link" data-ws-view="risk">Review my plan →</button>')}${card('Learn with your teacher','<p>Explore the reasoning behind your monthly plan.</p><button class="btn" type="button" data-workspace-ask="Help me understand my saved budget and the tradeoffs in my monthly plan. Teach me the reasoning without deciding for me.">Discuss my budget</button><button class="ws-link" type="button" data-learn-workspace>Learn the foundations →</button>')}</div></div><div data-ws-panel="risk" hidden>${card('Monthly plan review','<div id="budget-review"></div>')}</div><div data-ws-panel="improve" hidden>${card('Explore your tradeoffs','<p>Compare your spending, debt minimums and cushion goal with your teacher. Your saved inputs stay in your control.</p><div id="budget-tradeoffs"></div><button class="btn primary" type="button" data-workspace-ask="Help me explore the tradeoffs in my saved monthly budget. Show the arithmetic for spending, debt minimums and my cash cushion. Do not change my inputs or choose for me.">Explore with my teacher</button>')}</div><div data-ws-panel="holdings" hidden><article class="ws-card"><header class="ws-card-h"><h3>Build or update my budget</h3><span class="fine">Saved monthly inputs</span></header><form id="budget-builder"><div class="workspace-form"><label class="f">Income month<input type="month" name="month" id="budget-month" required></label>${field('income','Take-home income','income')}${field('bills','Monthly fixed bills','bills')}${field('spending','Monthly everyday spending','spending')}${field('savings','Cash savings','savings')}${field('cashCushion','My cash cushion goal','cushion')}</div><p class="fine">Enter 0 when none. Monthly totals replace saved bill/spending totals. Existing debts stay unchanged; edit debt details separately. Include costs you expect even if they do not occur every month.</p><div class="row"><button class="btn primary" type="submit">Save my budget</button><button class="btn" type="button" data-edit-finances>Edit debts & detailed inputs</button></div></form></article></div><div data-ws-panel="calendar" hidden>${card('Saved income history','<div id="budget-history" class="workspace-table"></div><p class="fine">Saved income months, not a transaction feed or bill due-date calendar.</p>')}</div><div data-ws-panel="settings" hidden>${card('My planning preferences','<p>Your cash cushion is your own goal. Update it alongside your monthly budget.</p><button class="btn" type="button" data-ws-view="holdings">Update my plan</button>')}</div></section><section id="workspace-portfolio" hidden><div data-ws-panel="overview"><div id="portfolio-overview" class="workspace-stats"></div><div class="ws-grid ws-two-one">${card('Position weights vs your limit','<div id="portfolio-weights" class="ws-bars"></div><p class="fine">Imported market values. Historical performance is not available from this import.</p>')}${card('Guideline review','<div id="portfolio-health"></div><button class="ws-link" type="button" data-ws-view="risk">Review checks →</button>')}</div><div class="ws-grid ws-three">${card('Sector exposure','<div id="portfolio-sectors"></div>')}${card('Upcoming earnings','<div id="portfolio-events-mini"><p class="fine">Refresh market context for dated events.</p></div><button class="ws-link" type="button" data-ws-view="calendar">Calendar →</button>')}${card('Latest on your holdings','<div id="portfolio-news-mini"><p class="fine">Refresh market context for available headlines.</p></div><button class="ws-link" type="button" data-ws-view="news">All news →</button>')}</div></div><div data-ws-panel="risk" hidden><div class="ws-grid ws-half">${card('Guideline checks','<div id="portfolio-checks"></div>')}${card('Portfolio risk metrics','<div id="portfolio-metrics"></div>')}</div></div><div data-ws-panel="improve" hidden>${card('Explore your portfolio tradeoffs','<p>Compare a value-only trim-to-cash scenario against the limits you set. Your imported baseline stays unchanged.</p><button class="btn primary" type="button" data-ws-view="settings">Open guidelines & what-if</button><div class="row"><button class="btn" type="button" data-workspace-ask="Explain the concentration and upcoming earnings events in my portfolio using my saved guidelines. Separate dated facts, researched principles, and interpretation. Do not recommend buying or selling.">Discuss my portfolio</button></div>')}</div><div data-ws-panel="holdings" hidden>${card('My imported holdings','<div class="row"><button class="btn primary" type="button" data-context>Import holdings</button><button class="btn" type="button" id="workspace-sample">Use sample holdings</button></div><div id="portfolio-holdings" class="workspace-table"></div>')}</div><div data-ws-panel="settings" hidden><article class="ws-card"><header class="ws-card-h"><h3>Your guidelines & what-if</h3></header><div id="workspace-guidelines"></div></article></div><div data-ws-panel="calendar" hidden>${card('Holdings & upcoming earnings '+help('quote','market quotes'),'<div id="workspace-market"><p>Refresh to see available context for your imported holdings.</p></div>')}<div class="ws-grid ws-half">${card('Economic calendar','<div id="workspace-economic"><p class="fine">Refresh market context to load available calendar snapshots.</p></div>')}${card('Macro backdrop','<div id="workspace-macro"><p class="fine">Refresh market context to load dated macro context.</p></div>')}</div></div><div data-ws-panel="news" hidden>${card('Headlines on your holdings','<div id="workspace-news"><p class="fine">Refresh market context to load available headlines.</p></div>')}</div><footer class="ws-market-footer"><button class="btn" type="button" id="workspace-market-refresh">Refresh market context</button><label><input type="checkbox" id="workspace-auto-refresh"> Refresh every five minutes while visible</label><p class="fine">On-demand context from configured providers or dated fallback data. Quotes do not revalue your imported portfolio.</p></footer></section></div></div></div>`;


// Match the reference hierarchy: four summaries, one wide chart, then detail and planning panels.
const budgetPanel=root.querySelector('#workspace-budget [data-ws-panel="overview"]');
const budgetStats=root.querySelector('#budget-overview'),cashflowCard=root.querySelector('#budget-cashflow').closest('.ws-card'),allocationCard=root.querySelector('#budget-allocation').closest('.ws-card'),cushionCard=root.querySelector('#budget-cushion').closest('.ws-card');
cashflowCard.classList.add('budget-dashboard-overview');cashflowCard.querySelector('h3').textContent='Money in, money out';
root.querySelector('#budget-cashflow').classList.remove('ws-bars');
allocationCard.querySelector('h3').textContent='Spending by category';cushionCard.querySelector('h3').textContent='Your next step';
const nextStep=root.querySelector('#budget-next');cushionCard.append(nextStep);
const coachingActions=document.createElement('div');coachingActions.className='budget-coaching-actions';coachingActions.innerHTML='<button type="button" class="btn primary" data-workspace-ask="Help me understand the tradeoffs in my saved budget. Ask one question at a time and help me choose a practical next step.">Talk to my teacher</button><button type="button" class="ws-link" data-learn-workspace>Explore a lesson</button>';
cushionCard.append(coachingActions);
const teacherCard=document.createElement('article');teacherCard.className='budget-teacher-card';teacherCard.innerHTML='<div class="budget-teacher-heading"><img src="/img/mentor-logo-suede.webp" alt="Mentor Labs" width="32" height="32"><div><strong>Ask your teacher</strong><p>Talk through your plan, one step at a time.</p></div><span aria-label="Teacher available" class="budget-teacher-dot"></span></div><button type="button" data-workspace-ask="Help me understand my budget and choose a practical next step." class="budget-teacher-prompt">Ask about these numbers… <span aria-hidden="true">↗</span></button>';
const planningColumn=document.createElement('div');planningColumn.className='budget-planning-column';planningColumn.append(cushionCard,teacherCard);
const budgetLower=document.createElement('div');budgetLower.className='budget-dashboard-lower';budgetLower.append(allocationCard,planningColumn);budgetPanel.replaceChildren(budgetStats,cashflowCard,budgetLower);

document.querySelector('#workspace-guidelines').append(document.querySelector('#portfolio-guidelines'));
const renderAdvanced=mountSentinel(root);
const exactPortfolio=document.createElement('section');exactPortfolio.id='exact-portfolio';exactPortfolio.hidden=true;
exactPortfolio.innerHTML='<div class="exact-workspace-tabs"><button type="button" class="btn" data-exact-budget>Budget</button><button type="button" class="btn primary" aria-current="page">Portfolio</button></div><iframe id="exact-portfolio-frame" src="/portfolio-demo/index.html" title="Investment portfolio dashboard" loading="lazy"></iframe>';
root.append(exactPortfolio);
const exactFrame=exactPortfolio.querySelector('iframe');
exactPortfolio.querySelector('[data-exact-budget]').onclick=()=>root.querySelector('[data-workspace-tab="budget"]').click();
function hydrateExactPortfolio(){if(!current)return;try{exactFrame.contentWindow.MentorPortfolio?.hydrate({workspace:previewPortfolio?demo:current,market:previewPortfolio?demo?.marketContext:marketData,sample:previewPortfolio});}catch(error){status('Portfolio view could not update: '+error.message);try{exactFrame.contentWindow.MentorPortfolio?.status('Portfolio view could not update. Please refresh.');}catch{}}}
function syncExactPortfolio(){const visible=workspace==='portfolio';exactPortfolio.hidden=!visible;root.querySelector('.ws-shell').hidden=visible;document.body.classList.toggle('exact-portfolio-active',visible&&!document.querySelector('#v-workspace').hidden);if(visible)hydrateExactPortfolio();}


function navigate(next=view){view=next;for(const panel of root.querySelectorAll('[data-ws-panel]'))panel.hidden=panel.dataset.wsPanel!==view;document.querySelector('#workspace-budget').hidden=workspace!=='budget';document.querySelector('#workspace-portfolio').hidden=workspace!=='portfolio';for(const b of root.querySelectorAll('[data-ws-view]'))b.setAttribute('aria-pressed',String(b.dataset.wsView===view));const labels=workspace==='portfolio'?{overview:'Overview',risk:'Risk review',improve:'Explore tradeoffs',holdings:'Holdings',calendar:'Calendar',news:'News',settings:'Guidelines'}:{overview:'Overview',calendar:'Cash flow',holdings:'Spending',improve:'Debt plan',news:'Goals',risk:'Review',settings:'Settings'};for(const b of root.querySelectorAll('.ws-nav [data-ws-view]')){b.hidden=false;b.querySelector('span').textContent=labels[b.dataset.wsView]||'News';}document.querySelector('#ws-view-title').textContent=workspace==='budget'&&view==='overview'?'Your monthly plan':labels[view]||'Overview';document.querySelector('#ws-workspace-label').textContent=workspace==='portfolio'?'Portfolio workspace':'Budget workspace';document.querySelector('#ws-view-sub').textContent=workspace==='portfolio'?'Imported holdings · Your guidelines':'Your saved monthly plan';document.querySelector('#ws-primary-action').textContent=workspace==='portfolio'?'Import holdings':'Update budget';if(view==='settings'&&workspace==='portfolio'){const details=document.querySelector('#portfolio-guidelines>details');if(details)details.open=true;}renderSources();renderPreview();syncExactPortfolio();const db=document.querySelector('#demo-budget-tabs');if(db)db.hidden=workspace!=='budget';}


function renderPreview(){
 root.dataset.sampleBudget=String(previewBudget);root.dataset.samplePortfolio=String(previewPortfolio);
 const sample=workspace==='budget'?previewBudget:previewPortfolio,banner=document.querySelector('#workspace-preview');
 banner.hidden=true;document.querySelector('#ws-view-sub').textContent='Alex Morgan · Fictional financial profile';document.querySelector('#ws-source-description').textContent='Simulated financial profile';document.querySelector('#ws-source-date').textContent='Shared with your teacher';document.querySelector('#ws-primary-action').textContent='Ask your teacher';

}
function renderSources(){if(workspace==='portfolio')document.querySelector('#ws-view-sub').textContent=current?.review.source==='sample_synthetic'?'Synthetic sample holdings · Your guidelines':'Imported holdings · Your guidelines';document.querySelector('#ws-source-description').textContent=workspace==='budget'?'Your saved monthly inputs':marketData?'Imported holdings · market context':'Your imported holdings';document.querySelector('#ws-source-date').textContent=workspace==='budget'?'No linked bank account':marketData?.retrievedAt?'Context retrieved '+new Date(marketData.retrievedAt).toLocaleString():'Quotes not refreshed';renderPreview();}

function bars(rows,{limit=null,format=usd}={}){const valid=rows.filter(r=>Number.isFinite(Number(r.value))&&Number(r.value)>=0),max=Math.max(...valid.map(r=>Number(r.value)),Number(limit)||0,1);return valid.length?valid.map(r=>`<div class="ws-bar-row"><div><span>${esc(r.label)}</span><strong>${esc(format(r.value))}</strong></div><div class="ws-bar-track"><span style="width:${Math.min(100,Number(r.value)/max*100)}%;--bar-color:${r.warning?'var(--ochre)':'var(--green)'}"></span>${limit!=null?`<i style="left:${Math.min(100,Number(limit)/max*100)}%" title="Your limit"></i>`:''}</div></div>`).join(''):'<p class="ws-empty">Add your inputs to see this view.</p>';}

function donut(rows,total,label){const positive=rows.filter(r=>Number(r.value)>0),colors=['var(--green)','#6c8b72','#b4bea0','#c2a878','#92876e'];if(!positive.length||!(total>0))return '<p class="ws-empty">No allocation data entered yet.</p>';let end=0;const gradient=positive.map((r,i)=>{const start=end;end+=Number(r.value)/total*100;return `${colors[i%colors.length]} ${start}% ${end}%`;}).join(',');return `<div class="ws-donut" role="img" aria-label="${esc(label)}" style="background:conic-gradient(${gradient})"><span>${esc(label)}</span></div><ul class="ws-legend">${positive.map((r,i)=>`<li><i style="background:${colors[i%colors.length]}"></i><span>${esc(r.label)}</span><strong>${pct(Number(r.value)/total)}</strong></li>`).join('')}</ul>`;}

function metrics(rows){return `<dl class="ws-metrics">${rows.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>`;}

function kpis(rows){return rows.map(([label,value,id,note])=>`<article><span>${esc(label)} ${id?help(id,label):''}</span><strong>${esc(value)}</strong>${note?`<small>${esc(note)}</small>`:''}</article>`).join('');}

function budgetTimeline(history,costs){
 const points=(history||[]).map(h=>({month:String(h.month),value:Number(h.amount)})).filter(h=>Number.isFinite(h.value));if(!points.length)return '<p class="ws-empty">Add income to see your overview.</p>';
 const peakValue=Math.max(...points.map(p=>p.value),costs,1),interval=10**Math.floor(Math.log10(peakValue)),top=Math.ceil(peakValue*1.1/interval)*interval,left=64,right=970,bottom=248,height=210;
 const x=i=>points.length===1?(left+right)/2:left+i/(points.length-1)*(right-left),y=v=>bottom-v/top*height;
 const path=points.map((p,i)=>(i?'L':'M')+x(i)+','+y(p.value)).join(' '),area=path+' L'+x(points.length-1)+','+bottom+' L'+x(0)+','+bottom+' Z';
 const label=m=>/^\d{4}-\d{2}$/.test(m)?new Date(m+'-15T12:00:00Z').toLocaleDateString('en-US',{month:'short',year:'numeric',timeZone:'UTC'}):m;
 return '<div class="budget-chart-key"><span><i></i>Take-home income</span><span><i class="planned"></i>Current planned costs</span></div><svg preserveAspectRatio="none" class="budget-timeline" viewBox="0 0 1000 290" role="img" aria-label="Saved monthly income compared with current planned costs"><title>Saved take-home income; the cost line repeats the current monthly plan, not historical spending.</title>'+[0,1,2,3,4].map(i=>{const v=top*i/4,cy=y(v);return '<line x1="'+left+'" y1="'+cy+'" x2="'+right+'" y2="'+cy+'" class="budget-chart-grid"/><text x="6" y="'+(cy+4)+'">'+esc(new Intl.NumberFormat('en-US',{notation:'compact',style:'currency',currency:'USD',maximumFractionDigits:1}).format(v))+'</text>';}).join('')+'<path d="'+area+'" class="budget-chart-area"/><path d="'+path+'" class="budget-chart-income"/><line x1="'+left+'" y1="'+y(costs)+'" x2="'+right+'" y2="'+y(costs)+'" class="budget-chart-cost"/>'+points.map((p,i)=>'<circle cx="'+x(i)+'" cy="'+y(p.value)+'" r="3" class="budget-chart-dot"><title>'+esc(label(p.month)+': '+usd(p.value))+'</title></circle><text x="'+x(i)+'" y="278" text-anchor="middle">'+esc(label(p.month))+'</text>').join('')+'</svg>';
}

function render(data){const real=data;const changed=current?.review.snapshotId!==data.review.snapshotId||current?.review.guidelineVersion!==data.review.guidelineVersion;current=data;if(changed&&marketData){marketData=null;for(const id of ['workspace-market','workspace-news','workspace-economic','workspace-macro','portfolio-events-mini','portfolio-news-mini'])document.querySelector('#'+id).textContent='Holdings or review guidelines changed. Refresh market context.';}previewBudget=true;previewPortfolio=true;if(demo){const budgetProfile=previewBudget?demo.profile:(real.profile||{});data={...real,budget:previewBudget?demo.budget:real.budget,profile:{...real.profile,...budgetProfile,portfolio:previewPortfolio?demo.profile.portfolio:real.profile.portfolio},review:previewPortfolio?demo.review:real.review,advancedRisk:previewPortfolio?demo.advancedRisk:real.advancedRisk,guidelines:previewPortfolio?demo.guidelines:real.guidelines};}displayed=data;renderDemoBudget(data);const b=data.budget,s=b.snapshot,p=data.profile||{},income=Number(s.lowestMonth),costs=Number(s.essentialsTotal),savings=Number(s.savings),goal=Number(b.cashCushion),r=data.review,holdings=p.portfolio?.securities||[],total=Number(r.marketValue)||0;

 document.querySelector('#budget-overview').innerHTML=kpis([['Take-home income',b.ready?usd(s.lowestMonth):'Add income','income','Lowest saved month'],['Planned spending',usd(s.essentialsTotal),'bills','Includes debt minimums'],['Available',b.ready?usd(b.monthlyBalance):'Incomplete','balance','After entered costs'],['Cash cushion gap',usd(b.reserveGap),'cushion','Your own goal']]);

 document.querySelector('#budget-cashflow').innerHTML=b.ready?budgetTimeline(p.incomeHistory,costs):'<p class="ws-empty">Enter your take-home income to compare it with your monthly plan.</p><button class="btn" type="button" data-ws-view="holdings">Build my budget</button>';

 const cushionProgress=b.cashCushion!=null&&goal>0?Math.min(100,savings/goal*100):0;document.querySelector('#budget-cushion').innerHTML=b.cashCushion==null?'<p class="ws-empty">Choose a cash cushion goal in your budget inputs.</p>':`<div class="budget-goal-heading"><strong>Cash cushion goal</strong><span>${Math.round(cushionProgress)}%</span></div><p class="budget-goal-amount">${usd(s.savings)} <span>of ${usd(b.cashCushion)}</span></p><div class="budget-goal-track" role="progressbar" aria-label="Cash cushion goal" aria-valuenow="${Math.round(cushionProgress)}" aria-valuemin="0" aria-valuemax="100"><span style="width:${cushionProgress}%"></span></div><p class="fine">${goal===0?'Your goal is set to zero.':usd(b.reserveGap)+' remaining to your goal.'}</p>`;

 const allocation=[{label:'Fixed bills',value:s.fixedBillsTotal},{label:'Everyday spending',value:s.expensesTotal},{label:'Debt minimums',value:s.debtMinimumsTotal}];document.querySelector('#budget-allocation').innerHTML='<div class="budget-spending-list"><div class="budget-spending-labels"><span>Category</span><span>Amount</span><span>Share of lowest income</span></div>'+allocation.map((row,i)=>'<div class="budget-spending-row"><span class="budget-row-icon" aria-hidden="true">'+['B','S','D'][i]+'</span><div><strong>'+esc(row.label)+'</strong><small>Monthly plan</small></div><b>'+usd(row.value)+'</b><div class="budget-spending-share"><span class="budget-category-track"><i style="width:'+Math.min(100,income>0?Number(row.value)/income*100:0)+'%"></i></span><small>'+ (income>0?pct(Number(row.value)/income):'—')+'</small></div></div>').join('')+'<div class="budget-spending-total"><strong>Total planned costs</strong><b>'+usd(s.essentialsTotal)+'</b></div></div>';

 const reviewText=!b.ready?'Your plan needs complete income and cost inputs.':Number(b.monthlyBalance)<0?'Entered costs exceed your lowest saved take-home month.':Number(b.monthlyBalance)===0?'Your entered plan uses all of your lowest saved take-home month.':'Your entered plan leaves '+usd(b.monthlyBalance)+' after monthly costs.';document.querySelector('#budget-next').innerHTML=`<p>${esc(reviewText)}</p>`;document.querySelector('#budget-review').innerHTML=`<div class="ws-alert">${esc(reviewText)}</div>${metrics([['Fixed bills',usd(s.fixedBillsTotal)],['Everyday spending',usd(s.expensesTotal)],['Debt minimums',usd(s.debtMinimumsTotal)],['Total debt entered',usd(s.debtTotal)],['Cash savings',usd(s.savings)],['Cushion gap',usd(b.reserveGap)]])}<p class="fine">${esc(b.note)}</p><button class="btn" type="button" data-ws-view="holdings">Review my inputs</button>`;document.querySelector('#budget-tradeoffs').innerHTML=`${metrics([['Available',b.ready?usd(b.monthlyBalance):'Incomplete'],['Cash cushion goal',usd(b.cashCushion)],['Cash cushion gap',usd(b.reserveGap)]])}<p class="fine">A positive planned balance covers only the costs you entered. It is not a forecast.</p>`;

 const history=(p.incomeHistory||[]).slice().sort((a,b)=>a.month.localeCompare(b.month));document.querySelector('#budget-history').innerHTML=history.length?`<table><thead><tr><th>Month</th><th>Take-home income</th></tr></thead><tbody>${history.map(x=>`<tr><td>${esc(x.month)}</td><td>${usd(x.amount)}</td></tr>`).join('')}</tbody></table>`:'<p class="ws-empty">No income months saved.</p>';const last=history.at(-1);document.querySelector('#budget-month').value=last?.month||new Date().toISOString().slice(0,7);for(const [id,value]of Object.entries({income:last?.amount,bills:p.bills?.length?s.fixedBillsTotal:null,spending:p.expenses?.length?s.expensesTotal:null,savings:p.savings,cashCushion:b.cashCushion}))document.querySelector('#budget-'+id).value=value??'';

 const grouped=new Map();for(const h of holdings)grouped.set(h.name,(grouped.get(h.name)||0)+Number(h.value));const positions=[...grouped].map(([label,value])=>({label,value})).sort((a,b)=>b.value-a.value);document.querySelector('#portfolio-overview').innerHTML=kpis([['Portfolio value',usd(r.marketValue),null,r.source==='sample_synthetic'?'Synthetic sample':'Imported snapshot'],['Holdings',String(positions.length),'holdings','Distinct imported names'],['Largest position',total>0?pct((positions[0]?.value||0)/total):'No holdings','position','Share of imported value'],['Review flags',String(r.breaches.length),null,r.unknownChecks.length+' checks unknown']]);document.querySelector('#ws-alert-count').textContent=String(r.breaches.length);document.querySelector('#ws-alert-count').hidden=!r.breaches.length;

 const limit=data.guidelines?.maxPositionPercent;document.querySelector('#portfolio-weights').innerHTML=total>0?bars(positions.map(h=>({...h,value:h.value/total*100,warning:limit!=null&&!/^(CASH|USD|US DOLLAR)$/i.test(h.label)&&h.value/total*100>limit})),{limit,format:v=>Number(v).toFixed(1)+'%'})+(limit!=null?`<p class="fine">Vertical marker: your ${esc(limit)}% single-security limit. Cash is not checked against this rule.</p>`:'<p class="fine">Set your own guideline to compare position weights with a limit.</p>'):'<p class="ws-empty">Import valued holdings to see allocation and concentration.</p><button class="btn" type="button" data-context>Import holdings</button>';

 const known=r.checks.filter(c=>c.status!=='unknown'),passed=known.filter(c=>c.status==='pass').length;document.querySelector('#portfolio-health').innerHTML=`<div class="ws-score"><div class="ws-ring" style="--p:${known.length?passed/known.length*100:0}"><b>${known.length?passed+'/'+known.length:'—'}</b></div><p><strong>${known.length?'Checks passing':'Not evaluated'}</strong><br>${r.breaches.length} flagged · ${r.unknownChecks.length} unknown</p></div><p class="fine">Against your saved guidelines. This is not a suitability or return score.</p>`;

 document.querySelector('#portfolio-checks').innerHTML=r.checks.map(c=>`<article class="ws-alert ${c.status==='breach'?'ws-warning':''}"><strong>${esc(c.symbol||'Coverage check')} <span class="ws-pill">${esc(c.status)}</span></strong><p>${esc(c.reason||(c.observed!=null?c.observed+' holdings / minimum '+c.minimum:c.percent+'% / '+c.limitPercent+'% limit'))}</p></article>`).join('');document.querySelector('#portfolio-metrics').innerHTML=metrics([['Imported value',usd(r.marketValue)],['Valuation date',r.coverage.priceFreshness],['Guideline version',r.guidelineVersion??'Not set'],['Largest position',total>0?pct((positions[0]?.value||0)/total):'Unknown'],['Top five share',total>0?pct(positions.filter(x=>! /^(CASH|USD|US DOLLAR)$/i.test(x.label)).slice(0,5).reduce((n,x)=>n+x.value,0)/total):'Unknown']])+`<p class="fine">${esc(r.coverage.scope)}</p>`;

 const sectors=p.portfolio?.sectors||[];document.querySelector('#portfolio-sectors').innerHTML=sectors.length&&total>0&&sectors.every(x=>x.name&&!/^unknown$/i.test(x.name))&&Math.abs(sectors.reduce((sum,x)=>sum+Number(x.value),0)-total)<0.01?donut(sectors.map(x=>({label:x.name,value:x.value})),total,'Imported sectors'):'<p class="ws-empty">Your import does not include a complete sector allocation. Sector coverage stays unknown.</p>';

 document.querySelector('#portfolio-holdings').innerHTML=holdings.length?`<table><caption>Imported values, not a live account balance</caption><thead><tr><th>Holding</th><th>Imported value</th><th>Share</th></tr></thead><tbody>${positions.map(h=>`<tr><td><strong>${esc(h.label)}</strong></td><td>${usd(h.value)}</td><td>${total>0?pct(h.value/total):'Unknown'}</td></tr>`).join('')}</tbody></table>`:'<p class="ws-empty">Import a holdings CSV or use the labeled sample.</p>';renderSources();renderAdvanced(previewPortfolio?demo?.advancedRisk:(marketData?.riskAnalysis||data.advancedRisk));if(previewBudget){const p=real.profile||{},last=(p.incomeHistory||[]).slice().sort((a,b)=>a.month.localeCompare(b.month)).at(-1);document.querySelector('#budget-month').value=last?.month||new Date().toISOString().slice(0,7);const sum=rows=>rows?.length?rows.reduce((n,r)=>n+Number(r.amount),0).toFixed(2):'';for(const[id,value]of Object.entries({income:last?.amount,bills:sum(p.bills),spending:sum(p.expenses),savings:p.savings,cashCushion:real.budget.cashCushion}))document.querySelector('#budget-'+id).value=value??'';}if(previewPortfolio&&demo){renderMarketContext(demo.marketContext);}renderPreview();document.dispatchEvent(new CustomEvent('mentor:workspace-rendered',{detail:{sampleBudget:previewBudget,samplePortfolio:previewPortfolio}}));hydrateExactPortfolio();}

async function refresh(){const real=await api('/api/workspace');if(!demo)demo=await api('/api/workspace/demo');render(real);document.dispatchEvent(new CustomEvent('mentor:portfolio-updated'));status('');}

function eventMarkup(events){return events.length?events.map(e=>`<article class="ws-event"><div class="ws-date">${esc(e.date)}</div><div><strong>${esc(e.symbol||e.title)}</strong><p class="fine">${esc(e.source)} · ${esc(e.sourceAsOf||'Date coverage unknown')}</p>${e.symbol?`<button class="ws-link" type="button" data-workspace-ask="${esc('Explain the upcoming earnings event for '+e.symbol+'. What questions should I listen for through my selected teacher’s researched perspective? Separate confirmed facts from interpretation. Do not predict returns or recommend trades.')}">Explain this event →</button>`:`<p>${esc(e.description||'')}</p>`}</div></article>`).join(''):'<p class="ws-empty">No known events in this window. Missing coverage does not mean no event is scheduled.</p>';}

function newsMarkup(items){return items?.length?items.map(n=>`<article class="ws-news"><span class="ws-pill">${esc(n.symbol)}</span><a href="${esc(n.url)}" target="_blank" rel="noopener noreferrer">${esc(n.title)}</a><p class="fine">${esc(n.source)} · ${esc(n.date||'Date unknown')} · ${esc(n.provider||'')} ${esc(n.providerAsOf||'')}</p></article>`).join(''):'<p class="ws-empty">No available headlines returned for these holdings.</p>';}

function renderMarketContext(d){renderAdvanced(d.riskAnalysis);document.querySelector('#workspace-market').innerHTML=`<p class="fine">${esc(d.note)} ${d.retrievedAt?'Retrieved '+esc(new Date(d.retrievedAt).toLocaleString()):''}</p><div class="workspace-table"><table><caption>Quotes for imported holdings; imported values are unchanged</caption><thead><tr><th>Symbol</th><th>Quote</th><th>Price date</th><th>Source</th></tr></thead><tbody>${d.holdings.map(h=>`<tr><td>${esc(h.symbol)}</td><td>${usd(h.price)}</td><td>${esc(h.priceAsOf||'Unknown')}</td><td>${esc(h.priceSource)}</td></tr>`).join('')}</tbody></table></div><h3>Upcoming earnings</h3><p class="fine">${esc(d.windowSource||'')} ${d.windowDays?esc(d.windowDays)+' days':''}. Scheduled events can change.</p>${eventMarkup(d.events)}${d.uncovered.length?`<p class="fine">Not retrieved: ${esc(d.uncovered.join(', '))}. The provider covers up to twelve symbols per request.</p>`:''}`;document.querySelector('#portfolio-events-mini').innerHTML=eventMarkup(d.events.slice(0,3));document.querySelector('#workspace-news').innerHTML=newsMarkup(d.news);document.querySelector('#portfolio-news-mini').innerHTML=newsMarkup(d.news?.slice(0,3));document.querySelector('#workspace-economic').innerHTML=eventMarkup(d.economicEvents||[]);const macro=d.macro;document.querySelector('#workspace-macro').innerHTML=macro?metrics([['Fed funds',macro.fedFunds==null?'Unknown':macro.fedFunds+'%'],['10Y Treasury',macro.tenYear==null?'Unknown':macro.tenYear+'%'],['2Y Treasury',macro.twoYear==null?'Unknown':macro.twoYear+'%'],['CPI YoY',macro.cpiYoY==null?'Unknown':macro.cpiYoY+'%'],['Unemployment',macro.unemployment==null?'Unknown':macro.unemployment+'%']])+`<p class="fine">${esc(macro.source)} · Snapshot ${esc(macro.snapshotAsOf||'unknown')}</p><p class="fine">${esc(typeof macro.asOfNotes==='string'?macro.asOfNotes:Object.entries(macro.asOfNotes||{}).map(([key,value])=>key+': '+value).join(' · '))}</p>`:'<p class="ws-empty">Macro context unavailable.</p>';renderSources();}

async function market(){if(previewPortfolio){renderMarketContext(demo.marketContext);status('Sample context uses dated snapshot data. Import holdings for your own review.');return;}if(refreshing)return;refreshing=true;document.querySelector('#workspace-market-refresh').disabled=true;status('Retrieving market context…');try{const requestedGuidelineVersion=current?.review.guidelineVersion;const d=await api('/api/workspace/market','POST',{});if(d.snapshotId!==current?.review.snapshotId||requestedGuidelineVersion!==current?.review.guidelineVersion){await refresh();throw Error('Holdings or review guidelines changed. Refresh market context again.');}marketData=d;renderMarketContext(d);hydrateExactPortfolio();status('Market context refreshed. Check each source and price date.');}finally{refreshing=false;document.querySelector('#workspace-market-refresh').disabled=false;}}

root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.workspaceTab){workspace=b.dataset.workspaceTab;for(const x of root.querySelectorAll('[data-workspace-tab]'))x.setAttribute('aria-pressed',String(x===b));navigate('overview');}if(b.dataset.wsView)navigate(b.dataset.wsView);if(b.id==='ws-primary-action'||b.hasAttribute('data-ws-add-own')){if(workspace==='portfolio')document.querySelector('#context-dialog').showModal();else document.dispatchEvent(new CustomEvent('mentor:workspace-question',{detail:{question:'Summarize the sample budget for Alex Morgan.'}}));}if(b.dataset.workspaceAsk)document.dispatchEvent(new CustomEvent('mentor:workspace-question',{detail:{question:b.dataset.workspaceAsk+' Use the shared fictional financial profile shown on the dashboard.'}}));if(b.hasAttribute('data-context'))document.querySelector('#context-dialog').showModal();if(b.hasAttribute('data-edit-finances'))document.dispatchEvent(new CustomEvent('mentor:edit-finances'));if(b.hasAttribute('data-learn-workspace'))document.dispatchEvent(new CustomEvent('mentor:show-learning'));});

document.querySelector('#budget-builder').onsubmit=e=>{e.preventDefault();const button=e.submitter||e.target.querySelector('button[type="submit"]');button.disabled=true;run(async()=>{try{await api('/api/workspace/budget','POST',Object.fromEntries(new FormData(e.target)));await refresh();document.dispatchEvent(new CustomEvent('mentor:inputs-updated'));navigate('overview');status('Budget saved. Your teacher uses these same inputs.');}finally{button.disabled=false;}});};

document.querySelector('#workspace-sample').onclick=()=>run(async()=>{await api('/api/portfolio/upload','POST',{sample:true});document.dispatchEvent(new CustomEvent('mentor:inputs-updated'));await refresh();navigate('overview');});

document.querySelector('#workspace-market-refresh').onclick=()=>run(market);

document.querySelector('#workspace-auto-refresh').onchange=e=>{clearInterval(watchTimer);if(e.target.checked)watchTimer=setInterval(()=>{if(!document.hidden&&!document.querySelector('#v-workspace').hidden&&workspace==='portfolio')run(market);},300000);};

document.querySelector('#ws-export').onclick=()=>{if(!current){status('Open the workspace to load your inputs before exporting.');return;}const blob=new Blob([JSON.stringify({workspace,sample:workspace==='budget'?previewBudget:previewPortfolio,exportedAt:new Date().toISOString(),...(workspace==='budget'?{budget:displayed.budget}:{review:displayed.review,fullRisk:previewPortfolio?demo.advancedRisk:marketData?.riskAnalysis||current.advancedRisk,holdings:displayed.profile?.portfolio,marketContext:previewPortfolio?demo.marketContext:marketData??null})},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='mentor-'+((workspace==='budget'?previewBudget:previewPortfolio)?'sample-':'')+workspace+'-review.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};

document.addEventListener('mentor:inputs-updated',()=>run(async()=>{const before=current?.review.snapshotId;await refresh();if(current?.review.snapshotId&&current.review.snapshotId!==before)await market();}));
document.addEventListener('mentor:workspace-open',()=>run(refresh));document.addEventListener('mentor:guidelines-updated',()=>run(refresh));document.querySelector('#context-dialog').addEventListener('close',()=>{if(!document.querySelector('#v-workspace').hidden)run(refresh);});navigate();

// Same-origin adapter for the imported, original Sentinel interface.
const approval=document.createElement('dialog');approval.id='exact-guideline-approval';approval.setAttribute('aria-label','Approve portfolio guidelines');document.body.append(approval);
const guidelineMap={maxPosition:'maxPositionPercent',maxSector:'maxSectorPercent',maxTop5:'maxTop5Percent',maxCrypto:'maxCryptoPercent',maxBeta:'maxBeta',maxVol:'maxVolatilityPercent',maxDrawdown:'maxDrawdownPercent',maxPE:'maxPE',minHoldings:'minHoldings',earningsWindow:'earningsWindowDays',maxLossFromCost:'maxLossFromCostPercent',maxFromHigh:'maxFromHighPercent',maxCorr:'maxCorrelation'};
const guidelineLabels={maxPosition:'Maximum single position (%)',maxSector:'Maximum sector exposure (%)',maxTop5:'Maximum top-five concentration (%)',maxCrypto:'Maximum crypto allocation (%)',maxBeta:'Maximum portfolio beta',maxVol:'Maximum annualized volatility (%)',maxDrawdown:'Maximum drawdown (%)',maxPE:'P/E valuation ceiling',minHoldings:'Minimum holdings',earningsWindow:'Earnings alert window (days)',maxLossFromCost:'Loss-from-cost review trigger (%)',maxFromHigh:'Maximum decline from 52-week high (%)',maxCorr:'Correlation threshold'};
async function reviewExactGuidelines(settings){
 const body=Object.fromEntries(Object.entries(guidelineMap).map(([source,key])=>[key,settings[source]]).filter(([,v])=>v!=null));
 Object.assign(body,{tickerLimits:settings.tickerLimits||{},sectorLimits:settings.sectorLimits||{},excludedSectors:settings.excluded||[],customRules:(settings.customRules||[]).map(r=>({...r,severity:r.severity||r.sev||'info'}))});
 const draft=await api('/api/portfolio/guidelines/draft','POST',body);
 approval.innerHTML='<h2>Review your guidelines</h2><p>Apply these review parameters to your own imported holdings. No trades are placed.</p><dl>'+Object.entries(guidelineMap).map(([label,key])=>'<div><dt>'+esc(guidelineLabels[label])+'</dt><dd>'+esc(draft[key]??'Not set')+'</dd></div>').join('')+'</dl><p>'+Object.keys(body.tickerLimits).length+' holding exceptions; '+Object.keys(body.sectorLimits).length+' sector exceptions; '+body.excludedSectors.length+' exclusions; '+body.customRules.length+' custom rules.</p><p role="status" id="exact-approval-status"></p><div class="row"><button type="button" class="btn primary" id="exact-approve">Approve and save</button><button type="button" class="btn" id="exact-cancel">Cancel</button></div>';
 approval.querySelector('#exact-cancel').onclick=()=>approval.close();
 approval.querySelector('#exact-approve').onclick=async e=>{e.target.disabled=true;try{await api('/api/portfolio/guidelines/save','POST',{draftId:draft.id,userConfirmation:true});approval.close();await refresh();document.dispatchEvent(new CustomEvent('mentor:guidelines-updated'));exactFrame.contentWindow.MentorPortfolio?.status('Your guidelines are saved.');}catch(error){approval.querySelector('#exact-approval-status').textContent=error.message;e.target.disabled=false;}};
 approval.showModal();
}
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==exactFrame.contentWindow||!e.data||typeof e.data.type!=='string')return;
 if(e.data.type==='mentor-portfolio-budget')root.querySelector('[data-workspace-tab=budget]').click();
 if(e.data.type==='mentor-portfolio-learning')document.dispatchEvent(new CustomEvent('mentor:show-learning'));
 if(e.data.type==='mentor-portfolio-ready')hydrateExactPortfolio();
 if(e.data.type==='mentor-portfolio-refresh')run(async()=>{try{await market();}catch(error){exactFrame.contentWindow.MentorPortfolio?.status(error.message);throw error;}});
 if(e.data.type==='mentor-portfolio-teacher'){document.querySelector('#teacher-launcher')?.click();if(typeof e.data.question==='string'){document.querySelector('#msg').value=e.data.question.slice(0,2000);document.querySelector('#msg').focus();}}
 if(e.data.type==='mentor-portfolio-guidelines')run(async()=>{try{await reviewExactGuidelines(e.data.settings||{});}catch(error){exactFrame.contentWindow.MentorPortfolio?.status(error.message);throw error;}});
 if(e.data.type==='mentor-portfolio-import')run(async()=>{try{await api('/api/portfolio/upload','POST',{csv:e.data.csv});await refresh();document.dispatchEvent(new CustomEvent('mentor:inputs-updated'));await market();}catch(error){exactFrame.contentWindow.MentorPortfolio?.status(error.message);throw error;}});
});
new MutationObserver(()=>{document.body.classList.toggle('exact-portfolio-active',workspace==='portfolio'&&!document.querySelector('#v-workspace').hidden);}).observe(document.querySelector('#v-workspace'),{attributes:true,attributeFilter:['hidden']});


// The presentation demo and teacher share the same server-generated fictional profile.
function renderDemoBudget(data){
 const original=document.querySelector('#workspace-budget');original.classList.add('demo-budget-original');
 let host=document.querySelector('#demo-budget-tabs');if(!host){host=document.createElement('section');host.id='demo-budget-tabs';original.after(host);}
 host.hidden=workspace!=='budget';
 const p=data.profile,b=data.budget,s=b.snapshot,income=Number(s.lowestMonth),cost=Number(s.essentialsTotal),saved=Number(s.savings),target=Number(b.cashCushion),debt=Number(s.debtTotal),minimum=Number(s.debtMinimumsTotal);
 const rows=[...(p.bills||[]),...(p.expenses||[]),{name:'Debt payments',amount:minimum}];
 const teacher='<article class="preview-teacher"><div class="preview-teacher-heading"><img src="/img/mentor-logo-suede.webp" width="30" height="30" alt=""><div><strong>Ask your teacher <span class="preview-dot"></span></strong><small>You have room to build your emergency fund.</small></div></div><button class="demo-ask" data-workspace-ask="Summarize this sample budget and explain my next step.">Ask about these numbers… <b>➤</b></button></article>';
 const stat=(items)=>'<div class="workspace-stats">'+kpis(items.map(([a,v,n])=>[a,v,null,n||'']))+'</div>';
 const table=(headers,rs)=>'<div class="demo-table-wrap"><table class="demo-table"><thead><tr>'+headers.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+rs.map(r=>'<tr>'+r.map(v=>'<td>'+v+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';
 const spending=table(['Category','Amount','Share of income'],rows.map((r,i)=>['<span class="demo-category">'+['⌂','◉','↗','◇','▤'][i%5]+'</span>'+esc(r.name),usd(r.amount),'<div class="demo-share"><i style="width:'+Math.min(100,Number(r.amount)/income*100)+'%"></i></div>'+pct(Number(r.amount)/income)]));
 const goalCard=card('Your next step','<h4>Emergency fund goal</h4><strong>'+usd(saved)+' <span class="fine">of '+usd(target)+'</span></strong><div class="demo-progress"><i style="width:'+Math.min(100,saved/target*100)+'%"></i></div><p class="fine">'+usd(Math.max(0,target-saved))+' to go · '+pct(saved/target)+' saved</p><hr><h4>Debt payoff</h4><p>'+usd(debt)+' across '+p.debts.length+' accounts</p><button class="ws-link" data-ws-view="improve">Explore debt plan →</button>');
 const chart=card('Money in, money out',budgetTimeline(p.incomeHistory,cost));
 const summary=stat([['Income',usd(income),'Lowest saved month'],['Planned spending',usd(cost)],['Available',usd(b.monthlyBalance)],['Emergency fund',(saved/cost).toFixed(1)+' months','Current cash / planned costs']]);
 const sections={};
 sections.overview=summary+chart+'<div class="demo-two">'+card('Spending by category',spending)+'<div>'+goalCard+teacher+'</div></div>';
 const history=table(['Month','Income','Planned costs','Balance'],p.incomeHistory.map(r=>[esc(r.month),usd(r.amount),usd(cost),usd(Number(r.amount)-cost)]));
 sections.calendar=summary+chart+'<div class="demo-two">'+card('Saved income history',history)+card('Costs: fixed vs. flexible',bars([{label:'Fixed bills',value:s.fixedBillsTotal},{label:'Everyday spending',value:s.expensesTotal},{label:'Debt payments',value:minimum}]))+'</div>'+teacher;
 sections.holdings=stat([['Total planned costs',usd(cost)],['Available',usd(b.monthlyBalance)]])+card('Spending by category',bars(rows.map(r=>({label:r.name,value:r.amount}))))+'<div class="demo-two">'+card('Monthly spending plan',spending)+card('Planned costs summary',metrics([['Total planned spending',usd(cost)],['Share of income',pct(cost/income)],['Available after spending',usd(b.monthlyBalance)],['Emergency fund goal',usd(target)]]))+'</div>'+teacher;
 const debts=table(['Debt','APR','Balance','Minimum'],p.debts.map(r=>[esc(r.name),(Number(r.rateBps)/100).toFixed(2)+'%',usd(r.balance),usd(r.minPayment)]));
 sections.improve=stat([['Total balance',usd(debt)],['Minimum payments',usd(minimum)+'/mo'],['Available to plan',usd(b.monthlyBalance)],['Accounts',String(p.debts.length)]])+card('Your debt balances',bars(p.debts.map(r=>({label:r.name,value:r.balance}))))+'<div class="demo-two">'+card('Your debts',debts)+card('Plan details','<label>Strategy<select id="demo-debt-strategy"><option>Snowball · smallest balance first</option><option>Avalanche · highest APR first</option></select></label><p class="fine">Compare the order with your teacher. Payments and interest determine the payoff date.</p><button class="btn primary" data-workspace-ask="Compare snowball and avalanche for the debts in this fictional profile, using the actual balances and APRs.">Explore with my teacher</button>')+'</div>'+teacher;
 sections.news=stat([['Emergency fund goal',usd(target)],['Saved',usd(saved)],['Remaining',usd(target-saved)],['Monthly available',usd(b.monthlyBalance)]])+'<div class="demo-two">'+goalCard+card('Cash cushion calculator',metrics([['Monthly planned costs',usd(cost)],['Target coverage',(target/cost).toFixed(1)+' months'],['Current coverage',(saved/cost).toFixed(1)+' months']])+'<p class="fine">The target belongs to this sample profile. Explore the tradeoffs with your teacher.</p>')+'</div>'+teacher;
 sections.risk=summary+card('Income vs. cost',bars([{label:'Income',value:income},{label:'Planned costs',value:cost}]))+'<div class="demo-two">'+card('Plan checklist','<div class="demo-check">✓ Income included</div><div class="demo-check">✓ Planned costs included</div><div class="demo-check">✓ Debt minimums covered</div><div class="demo-check">◷ Emergency fund in progress</div>')+card('Teacher-guided tradeoffs','<h3>'+usd(b.monthlyBalance)+' available</h3><p>Explore emergency savings, extra debt payments, and longer-term goals.</p><button class="btn primary" data-workspace-ask="Explain the tradeoffs for the available monthly balance in this fictional profile.">Talk it through</button>')+'</div>'+card('Plan arithmetic',spending)+teacher;
 sections.settings='<div class="demo-two">'+card('Income planning',metrics([['Planning basis','Lowest saved take-home month'],['Income',usd(income)]])+'<p class="fine">This demonstration uses Alex’s simulated financial profile.</p>')+goalCard+'</div><div class="demo-two">'+card('Detailed budget inputs',metrics([['Take-home income',usd(income)],['Fixed bills',usd(s.fixedBillsTotal)],['Everyday spending',usd(s.expensesTotal)],['Debt minimums',usd(minimum)],['Cash savings',usd(saved)]]))+card('Future account connection','<span class="ws-pill">Planned</span><p>Personal budget imports and bank connections are coming later.</p><button class="btn" disabled>Connect bank · planned</button><p class="fine">Your teacher can discuss every number in the sample profile now.</p>')+'</div>'+teacher;
 host.innerHTML=Object.entries(sections).map(([key,html])=>'<section data-ws-panel="'+key+'" '+(key!==view?'hidden':'')+'>'+html+'</section>').join('');
 const nav=root.querySelector('.ws-nav');for(const key of ['overview','calendar','holdings','improve','news','risk','settings'])nav.append(nav.querySelector('[data-ws-view="'+key+'"]'));
 root.querySelector('.workspace-connections').hidden=true;
 if(!root.querySelector('.preview-learning')){const learn=document.createElement('div');learn.className='preview-learning';learn.innerHTML='<button data-learn-workspace><strong>▣ &nbsp; Learning guide &nbsp; ›</strong><small>13-step program</small><div class=preview-progress><i></i></div></button><button data-workspace-ask="Help me understand this fictional profile."><span class=preview-dot></span> Teacher available &nbsp; ♧</button>';root.querySelector('.ws-sidebar').append(learn);}
}
